function XUiLifeTreeConstellationDetail:RefreshContent()
    local config = self._Control:GetLifeTreeConstellationConfigById(self.ConstellationId)
    -- 文字和图标
    self.TxtTitle.text = config.Names[self.ConstellationStateIndex]
    self.TxtDetail.text = XUiHelper.ConvertLineBreakSymbol(config.Descs[self.ConstellationStateIndex])
    self.RawImageIcon:SetRawImage(config.Icons[self.ConstellationStateIndex])
    
    -- 正逆神状态背景和颜色
    local clientConfig = self._Control:GetLifeTreeClientConfigConfigById("ConstellationStateColor")
    self.TxtJianbian.color = XUiHelper.Hexcolor2Color(clientConfig.Values[self.ConstellationStateIndex] or "#FFFFFF")
    local isPositive = self.ConstellationStateIndex == 1
    self.RawImageIconBlueBg.gameObject:SetActiveEx(isPositive)
    self.RawImageIconRedBg.gameObject:SetActiveEx(not isPositive)

    -- 神卡头像, 当前只取第一张神卡的图鉴配置，后续如果有多张神卡需要区分正逆神时再调整
    local divineCatalogId
    for _, catalogId in ipairs(config.CharacterCatalogIds) do
        local catalogConfig = self._Control:GetLifeTreeCharacterCatalogConfigById(catalogId)
        if catalogConfig and catalogConfig.CardType == XMVCA.XLifeTree.EnumConst.CARD_TYPE.DIVINE then
            divineCatalogId = catalogId
            break
        end
    end
    local divineState = self._Control:GetCharacterDivineState(divineCatalogId) -- 神卡状态

    if divineState == XMVCA.XLifeTree.EnumConst.DIVINE_TYPE.UNLOCK then
        -- 未解锁
        self.ImgUnlockedPositive.gameObject:SetActiveEx(false)
        self.ImgUnlockedReverse.gameObject:SetActiveEx(false)
    elseif divineState == XMVCA.XLifeTree.EnumConst.DIVINE_TYPE.POSITIVE then
        -- 正神解锁
        local catalogConfig = self._Control:GetLifeTreeCharacterCatalogConfigById(divineCatalogId)
        self.ImgIconPositive:SetRawImage(XMVCA.XCharacter:GetCharRoundnessHeadIcon(catalogConfig.CharacterId))
        self.ImgUnlockedPositive.gameObject:SetActiveEx(isPositive)
        self.ImgUnlockedReverse.gameObject:SetActiveEx(false)
    elseif divineState == XMVCA.XLifeTree.EnumConst.DIVINE_TYPE.REVERSE then
        -- 逆神解锁
        local catalogConfig = self._Control:GetLifeTreeCharacterCatalogConfigById(divineCatalogId)
        self.ImgIconReverse:SetRawImage(XMVCA.XCharacter:GetCharRoundnessHeadIcon(catalogConfig.CharacterId))
        self.ImgUnlockedPositive.gameObject:SetActiveEx(false)
        self.ImgUnlockedReverse.gameObject:SetActiveEx(not isPositive)
    end

    -- 切换按钮
    local hasSwitch = #config.Names > 1 and divineState == XMVCA.XLifeTree.EnumConst.DIVINE_TYPE.REVERSE
    if hasSwitch then
        self.BtnRightNext.gameObject:SetActiveEx(isPositive)
        self.BtnLeftNext.gameObject:SetActiveEx(not isPositive)
    else
        self.BtnLeftNext.gameObject:SetActiveEx(false)
        self.BtnRightNext.gameObject:SetActiveEx(false)
    end
end

